	public DBTraceTimeManager(DBHandle dbh, OpenMode openMode, ReadWriteLock @lock,
			TaskMonitor monitor, DBTrace trace, DBTraceThreadManager threadManager)
    {
		this.trace = trace;
		this.@lock = @lock;
		this.threadManager = threadManager;

		DBCachedObjectStoreFactory factory = trace.getStoreFactory();

		snapshotStore = factory.getOrCreateCachedStore(DBTraceSnapshot.TABLE_NAME,
			typeof(DBTraceSnapshot), (s, r) => new DBTraceSnapshot(this, s, r), true);
		snapshotsBySchedule = snapshotStore.getIndex(typeof(string), DBTraceSnapshot.SCHEDULE_COLUMN);

		forkStore = factory.getOrCreateCachedStore(DBTraceFork.TABLE_NAME, typeof(DBTraceFork),
			DBTraceFork.new, true);
		forksBySnap = forkStore.getIndex(typeof(long), DBTraceFork.SNAP_COLUMN);
	}

	/* @Override */
	public void dbError(IOException e) {
		trace.dbError(e);
